import java.util.*;

public class Main {
    static int[] frequencySort(int[] nums) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int n : nums) freq.merge(n, 1, Integer::sum);

        int[] result = nums.clone();
        int n = result.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n - 1 - i; j++) {
                int a = result[j], b = result[j + 1];
                boolean swap = freq.get(a) > freq.get(b) || (freq.get(a).equals(freq.get(b)) && a < b);
                if (swap) {
                    result[j] = b;
                    result[j + 1] = a;
                }
            }
        }
        return result;
    }

    public static void main(String[] args) {
        System.out.println(Arrays.toString(frequencySort(new int[]{1, 1, 2, 2, 2, 3})));
        System.out.println(Arrays.toString(frequencySort(new int[]{2, 3, 1, 3, 2})));
    }
}

